ui.css:
.hud-panel { font-family: 'Sniglet', 'Chewy', system-ui, sans-serif; color: #fff; padding: 6px 22px; border: 3px solid #3a1424; border-radius: 999px; background: linear-gradient(180deg, rgba(255,255,255,.6) 0%, rgba(255,255,255,.12) 45%, rgba(255,255,255,0) 55%, rgba(60,0,30,.18) 100%), radial-gradient(ellipse at 50% 120%, #ffb347 0%, #ff8a1a 45%, #e8590c 100%); box-shadow: 0 5px 0 #3a1424, inset 0 -4px 0 rgba(140,40,0,.25); }
.hud-panel .num { font: 400 38px/1.1 'Chewy', cursive; letter-spacing: 2px; text-shadow: 2.5px 0 0 #3a1424, -2.5px 0 0 #3a1424, 0 2.5px 0 #3a1424, 0 -2.5px 0 #3a1424, 1.8px 1.8px 0 #3a1424, -1.8px 1.8px 0 #3a1424, 1.8px -1.8px 0 #3a1424, -1.8px -1.8px 0 #3a1424, 0 4.5px 0 #3a1424; }
.bar { position: relative; width: 260px; height: 30px; background: linear-gradient(180deg, #3d1a14, #6a3624); border: 3px solid #3a1424; border-radius: 16px; box-shadow: 0 4px 0 #3a1424, inset 0 4px 6px rgba(0,0,0,.45); overflow: hidden; }
.bar-fill { position: relative; height: 100%; background: linear-gradient(180deg, rgba(255,255,255,.6) 0%, rgba(255,255,255,.12) 45%, rgba(255,255,255,0) 55%, rgba(60,0,30,.18) 100%), repeating-linear-gradient(-55deg, #ff2f55 0 12px, #fff5f7 12px 22px); border-radius: 0 13px 13px 0; box-shadow: inset 0 -3px 0 rgba(120,0,30,.25), inset -3px 0 0 rgba(255,255,255,.45); }
.bar-fill::after { content: ''; position: absolute; left: 9px; right: 12px; top: 4px; height: 5px; border-radius: 3px; background: rgba(255,255,255,.75); }
.bar-fill.mint { background: linear-gradient(180deg, rgba(255,255,255,.6) 0%, rgba(255,255,255,.12) 45%, rgba(255,255,255,0) 55%, rgba(60,0,30,.18) 100%), repeating-linear-gradient(-55deg, #35d0c0 0 11px, #effffb 11px 20px); }
